#include <stdio.h>

int main() {
    int a = 7, b = 2;
    printf("%d %d\n", a / b, a % b);        // 3 1

    int x = 5;
    printf("%s\n", (x > 0) ? "positive" : "non-positive");

    printf("%d\n", sizeof(int));             // typically 4
    printf("%d\n", 5 << 2);                   // 20 (5 * 2^2)
    return 0;
}
